from __future__ import annotations

from dataclasses import dataclass, replace
from decimal import Decimal, InvalidOperation
from typing import Protocol, TypeAlias


MoneyInput: TypeAlias = Decimal | int | float | str
_ZERO = Decimal("0")
_ONE_HUNDRED = Decimal("100")


class ShoppingCartError(Exception):
    """Base exception for shopping-cart operations."""


class InvalidProductNameError(ValueError, ShoppingCartError):
    """Raised when a product name is missing or invalid."""


class InvalidUnitPriceError(ValueError, ShoppingCartError):
    """Raised when a unit price is invalid."""


class InvalidQuantityError(ValueError, ShoppingCartError):
    """Raised when an item quantity is invalid."""


class ItemNotFoundError(KeyError, ShoppingCartError):
    """Raised when a requested product is not in the cart."""


class ConflictingUnitPriceError(ShoppingCartError):
    """Raised when an existing product is added with a different price."""


class InvalidDiscountError(ValueError, ShoppingCartError):
    """Raised when a discount value is invalid."""


def _normalize_product_name(product_name: str) -> str:
    if not isinstance(product_name, str):
        raise InvalidProductNameError(
            "Product name must be a string; "
            f"received {type(product_name).__name__}."
        )

    normalized_name = product_name.strip()
    if not normalized_name:
        raise InvalidProductNameError("Product name must not be empty.")

    return normalized_name


def _validate_quantity(quantity: int) -> int:
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise InvalidQuantityError(
            "Quantity must be an integer; "
            f"received {type(quantity).__name__}."
        )

    if quantity <= 0:
        raise InvalidQuantityError(
            f"Quantity must be greater than zero; received {quantity}."
        )

    return quantity


def _coerce_decimal(
    value: MoneyInput,
    *,
    field_name: str,
    error_type: type[ShoppingCartError],
) -> Decimal:
    if isinstance(value, bool):
        raise error_type(f"{field_name} must be numeric, not a boolean.")

    try:
        decimal_value = value if isinstance(value, Decimal) else Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as error:
        raise error_type(
            f"{field_name} must be a valid numeric value; received {value!r}."
        ) from error

    if not decimal_value.is_finite():
        raise error_type(f"{field_name} must be finite; received {value!r}.")

    return decimal_value


def _coerce_non_negative_decimal(
    value: MoneyInput,
    *,
    field_name: str,
    error_type: type[ShoppingCartError],
) -> Decimal:
    decimal_value = _coerce_decimal(
        value,
        field_name=field_name,
        error_type=error_type,
    )

    if decimal_value < _ZERO:
        raise error_type(
            f"{field_name} must not be negative; received {decimal_value}."
        )

    return decimal_value


@dataclass(frozen=True, slots=True)
class CartItem:
    """An immutable product entry stored in a shopping cart."""

    product_name: str
    unit_price: Decimal
    quantity: int

    def __post_init__(self) -> None:
        normalized_name = _normalize_product_name(self.product_name)
        normalized_price = _coerce_non_negative_decimal(
            self.unit_price,
            field_name="Unit price",
            error_type=InvalidUnitPriceError,
        )
        validated_quantity = _validate_quantity(self.quantity)

        object.__setattr__(self, "product_name", normalized_name)
        object.__setattr__(self, "unit_price", normalized_price)
        object.__setattr__(self, "quantity", validated_quantity)

    @property
    def line_total(self) -> Decimal:
        """Return the item's unit price multiplied by its quantity."""
        return self.unit_price * self.quantity


class _DiscountPolicy(Protocol):
    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        ...


@dataclass(frozen=True, slots=True)
class _PercentageDiscount:
    percentage: Decimal

    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        return subtotal * self.percentage / _ONE_HUNDRED


@dataclass(frozen=True, slots=True)
class _FlatDiscount:
    amount: Decimal

    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        return min(self.amount, subtotal)


class ShoppingCart:
    """
    Manage cart items and a single active discount.

    Monetary inputs are converted to ``Decimal`` to avoid binary floating-point
    arithmetic. Applying a discount replaces any previously active discount.
    Product names are trimmed and otherwise treated as case-sensitive.
    """

    def __init__(self) -> None:
        """Create an empty shopping cart without an active discount."""
        self._items: dict[str, CartItem] = {}
        self._discount: _DiscountPolicy | None = None

    def add_item(
        self,
        product_name: str,
        unit_price: MoneyInput,
        quantity: int = 1,
    ) -> CartItem:
        """
        Add an item and return its resulting cart entry.

        Adding an existing product increases its quantity when the supplied unit
        price matches. A conflicting price raises
        ``ConflictingUnitPriceError``.
        """
        normalized_name = _normalize_product_name(product_name)
        normalized_price = _coerce_non_negative_decimal(
            unit_price,
            field_name="Unit price",
            error_type=InvalidUnitPriceError,
        )
        validated_quantity = _validate_quantity(quantity)

        existing_item = self._items.get(normalized_name)
        if existing_item is None:
            added_item = CartItem(
                product_name=normalized_name,
                unit_price=normalized_price,
                quantity=validated_quantity,
            )
        else:
            if existing_item.unit_price != normalized_price:
                raise ConflictingUnitPriceError(
                    f"Product {normalized_name!r} already has unit price "
                    f"{existing_item.unit_price}; received {normalized_price}."
                )

            added_item = replace(
                existing_item,
                quantity=existing_item.quantity + validated_quantity,
            )

        self._items[normalized_name] = added_item
        return added_item

    def remove_item(self, product_name: str) -> CartItem:
        """Remove and return the item with the specified product name."""
        item = self._require_item(product_name)
        del self._items[item.product_name]
        return item

    def update_quantity(self, product_name: str, quantity: int) -> CartItem:
        """Set an existing item's quantity and return the updated entry."""
        existing_item = self._require_item(product_name)
        validated_quantity = _validate_quantity(quantity)
        updated_item = replace(existing_item, quantity=validated_quantity)
        self._items[existing_item.product_name] = updated_item
        return updated_item

    def calculate_subtotal(self) -> Decimal:
        """Return the total price of all items before discounts."""
        return sum(
            (item.line_total for item in self._items.values()),
            start=_ZERO,
        )

    def apply_percentage_discount(self, percentage: MoneyInput) -> None:
        """
        Apply a percentage discount, replacing any existing discount.

        The percentage must be between zero and one hundred, inclusive.
        """
        normalized_percentage = _coerce_non_negative_decimal(
            percentage,
            field_name="Percentage discount",
            error_type=InvalidDiscountError,
        )
        if normalized_percentage > _ONE_HUNDRED:
            raise InvalidDiscountError(
                "Percentage discount must not exceed 100; "
                f"received {normalized_percentage}."
            )

        self._discount = _PercentageDiscount(normalized_percentage)

    def apply_flat_discount(self, amount: MoneyInput) -> None:
        """
        Apply a flat discount, replacing any existing discount.

        A flat discount may exceed the current subtotal, but the resulting total
        will never be negative.
        """
        normalized_amount = _coerce_non_negative_decimal(
            amount,
            field_name="Flat discount",
            error_type=InvalidDiscountError,
        )
        self._discount = _FlatDiscount(normalized_amount)

    def clear_discount(self) -> None:
        """Remove the currently active discount, if one exists."""
        self._discount = None

    def calculate_total(self) -> Decimal:
        """Return the cart total after applying the active discount."""
        subtotal = self.calculate_subtotal()
        discount_amount = self._calculate_discount(subtotal)
        return subtotal - discount_amount

    def list_items(self) -> list[CartItem]:
        """
        Return a snapshot of all cart items in insertion order.

        The returned list may be modified without affecting the cart, and its
        ``CartItem`` entries are immutable.
        """
        return list(self._items.values())

    def clear(self) -> None:
        """Remove all items and reset the active discount."""
        self._items.clear()
        self._discount = None

    def _require_item(self, product_name: str) -> CartItem:
        normalized_name = _normalize_product_name(product_name)

        try:
            return self._items[normalized_name]
        except KeyError as error:
            raise ItemNotFoundError(
                f"No product named {normalized_name!r} exists in the cart."
            ) from error

    def _calculate_discount(self, subtotal: Decimal) -> Decimal:
        if self._discount is None:
            return _ZERO

        return self._discount.calculate_discount(subtotal)
